    12	function transformNumericKeysToArray(data: UnknownRecord): UnknownRecord | unknown[] {
    13	    const dataCopy = cloneDeep(data);
    14	    if (!isRecord(dataCopy)) {
    15	        return Array.isArray(dataCopy) ? (dataCopy as UnknownRecord[]).map(transformNumericKeysToArray) : (dataCopy as UnknownRecord);
    16	    }
    17	
    18	    const keys = Object.keys(dataCopy);
    19	
    20	    if (keys.length === 0) {
    21	        return dataCopy;
    22	    }
    23	    const allKeysAreNumeric = keys.every((key) => !Number.isNaN(Number(key)));
    24	    const keysAreSequential = keys.every((key, index) => parseInt(key, 10) === index);
    25	    if (allKeysAreNumeric && keysAreSequential) {
    26	        return keys.map((key) => transformNumericKeysToArray(dataCopy[key] as UnknownRecord));
    27	    }
    28	
    29	    for (const key in dataCopy) {
    30	        if (key in dataCopy) {
    31	            dataCopy[key] = transformNumericKeysToArray(dataCopy[key] as UnknownRecord);
    32	        }
    33	    }
    34	
    35	    return dataCopy;
    36	}
